using System.Collections.ObjectModel;
using System.Globalization;
using System.Text.Json;
using System.Windows.Input;
using LimosDispatch.Core.GenericRepository;
using LimosDispatch.Core.Helpers;
namespace LimosDispatch.Mobile.ViewModels;
public sealed record FinanceChoice(string Id,string Name,JsonElement Record){public override string ToString()=>Name;}
public sealed class PayBandEditor:ObservableObject{private string to="",value="",kind="fixed";private bool inclusive;public string To{get=>to;set=>Set(ref to,value);}public string Value{get=>value;set=>Set(ref this.value,value);}public string Kind{get=>kind;set=>Set(ref kind,value);}public bool Inclusive{get=>inclusive;set=>Set(ref inclusive,value);}public IReadOnlyList<string> Kinds{get;}=["fixed","percent"];}
public sealed class PaySystemsViewModel:BaseViewModel
{
 readonly FinanceService finance;readonly AuthService auth;readonly NavigationService nav;readonly IGenericRepository api;long version;string name="",type="bands",salary="",rate="";FinanceChoice? selected;
 public ObservableCollection<FinanceChoice> Systems{get;}=[];public ObservableCollection<PayBandEditor> Bands{get;}=[];public IReadOnlyList<string> Types{get;}=["bands","salary"];
 public FinanceChoice? Selected{get=>selected;set{if(Set(ref selected,value))Populate();}}public string Name{get=>name;set=>Set(ref name,value);}public string Type{get=>type;set{Set(ref type,value);Raise(nameof(IsSalary));}}public bool IsSalary=>Type=="salary";public string Salary{get=>salary;set=>Set(ref salary,value);}public string HourlyRate{get=>rate;set=>Set(ref rate,value);}
 public bool CanSave=>auth.User?.Can("Payouts",Selected is null?"Add":"Edit")==true;public bool CanDelete=>Selected is not null&&auth.User?.Can("Payouts","Delete")==true;
 public AsyncCommand SaveCommand{get;}public AsyncCommand DeleteCommand{get;}public AsyncCommand NewCommand{get;}public AsyncCommand AddBandCommand{get;}public ICommand RemoveBandCommand{get;}
 public PaySystemsViewModel(FinanceService finance,AuthService auth,NavigationService nav,IGenericRepository api){this.finance=finance;this.auth=auth;this.nav=nav;this.api=api;RefreshCommand=new(LoadAsync);SaveCommand=new(()=>Run(Save));DeleteCommand=new(()=>Run(Delete));NewCommand=new(()=>{Selected=null;Populate();return Task.CompletedTask;});AddBandCommand=new(()=>{Bands.Add(new());return Task.CompletedTask;});RemoveBandCommand=new Command<PayBandEditor>(b=>Bands.Remove(b));}
 public override Task LoadAsync()=>Run(async()=>{finance.Demand("Payouts");var rows=await finance.RecordsAsync("driverPaySystems");version=rows.Version;Systems.Clear();foreach(var r in rows.Rows)Systems.Add(new(FinanceService.Id(r),S(r,"name"),r.Clone()));if(Selected is not null)Selected=Systems.FirstOrDefault(s=>s.Id==Selected.Id);else if(Bands.Count==0&&Selected is not null&&Selected.Record.TryGetProperty("firstMiles",out _)){Bands.Add(new(){To=S(Selected.Record,"firstMiles"),Value=S(Selected.Record,"firstPay"),Kind="fixed",Inclusive=false});Bands.Add(new(){To=S(Selected.Record,"secondMiles"),Value=S(Selected.Record,"secondPay"),Kind="fixed",Inclusive=true});Bands.Add(new(){To="",Value=S(Selected.Record,"percent"),Kind="percent",Inclusive=false});}if(Bands.Count==0)Bands.Add(new());Raise(string.Empty);});
 static string S(JsonElement r,string key){if(!r.TryGetProperty(key,out var p))return "";var text=p.ToString();return key is "to" or "value" or "salary" or "hourlyRate" or "firstMiles" or "secondMiles" or "firstPay" or "secondPay" or "percent" && decimal.TryParse(text,NumberStyles.Number,CultureInfo.InvariantCulture,out var n)?n.ToString("0.########",LocalizationService.NumericCulture):text;}
 void Populate(){Name=Selected is null?"":S(Selected.Record,"name");Type=Selected is null?"bands":S(Selected.Record,"type");Salary=Selected is null?"":S(Selected.Record,"salary");HourlyRate=Selected is null?"":string.IsNullOrWhiteSpace(S(Selected.Record,"hourlyRate"))?"0":S(Selected.Record,"hourlyRate");Bands.Clear();if(Selected is not null&&Selected.Record.TryGetProperty("bands",out var b)&&b.ValueKind==JsonValueKind.Array)foreach(var row in b.EnumerateArray())Bands.Add(new(){To=S(row,"to"),Value=S(row,"value"),Kind=S(row,"kind"),Inclusive=S(row,"inclusive")=="True"||S(row,"inclusive")=="true"});if(Bands.Count==0&&Selected is not null&&Selected.Record.TryGetProperty("firstMiles",out _)){Bands.Add(new(){To=S(Selected.Record,"firstMiles"),Value=S(Selected.Record,"firstPay"),Kind="fixed",Inclusive=false});Bands.Add(new(){To=S(Selected.Record,"secondMiles"),Value=S(Selected.Record,"secondPay"),Kind="fixed",Inclusive=true});Bands.Add(new(){To="",Value=S(Selected.Record,"percent"),Kind="percent",Inclusive=false});}if(Bands.Count==0)Bands.Add(new());Raise(string.Empty);}
 public static decimal Number(string value){if(!InputValidation.TryDecimal(value,LocalizationService.Culture,out var n)||n<0||n>100000000)throw new InvalidOperationException("Enter a valid non-negative amount.");return n;}
 async Task Save(){finance.Demand("Payouts",Selected is null?"Add":"Edit");if(string.IsNullOrWhiteSpace(Name)||Name.Length>100)throw new InvalidOperationException("Enter a pay system name.");var patch=new Dictionary<string,object?>{["name"]=Name.Trim(),["type"]=Type};if(IsSalary)patch["salary"]=Number(Salary);else{patch["hourlyRate"]=Number(HourlyRate);var bands=new List<object>();decimal previous=0;for(var i=0;i<Bands.Count;i++){var b=Bands[i];decimal? to=string.IsNullOrWhiteSpace(b.To)?null:Number(b.To);if(to is null&&i!=Bands.Count-1||to is not null&&to<=previous||b.Kind is not("fixed" or "percent"))throw new InvalidOperationException("Use increasing band limits; only the last band may be unlimited.");var amount=Number(b.Value);if(b.Kind=="percent"&&amount>100)throw new InvalidOperationException("Percentage must be between 0 and 100.");bands.Add(new{to,inclusive=b.Inclusive,kind=b.Kind,value=amount});previous=to??previous;}if(bands.Count==0)throw new InvalidOperationException("Add at least one pay band.");patch["bands"]=bands;}
 if(!await nav.ConfirmAsync("Save pay system",LocalizationService.Text("Save these pay rules? Finalized statements will retain their existing rules.")))return;
 if(Selected is not null)await finance.UpdateAsync("driverPaySystems",Selected.Id,Selected.Record,patch,version,"Payouts");else{var current=await finance.RecordsAsync("driverPaySystems");patch["id"]="PS-"+Guid.NewGuid();await api.PostAsync<JsonElement>("api/records/driverPaySystems",new{version=current.Version,record=patch});}Selected=null;Populate();await Reload();}
 async Task Reload(){var rows=await finance.RecordsAsync("driverPaySystems");version=rows.Version;Systems.Clear();foreach(var r in rows.Rows)Systems.Add(new(FinanceService.Id(r),S(r,"name"),r.Clone()));Raise(string.Empty);}
 async Task Delete(){if(Selected is null)return;var w=await finance.WorkspaceAsync();var drivers=FinanceService.Read(w,"drivers",new List<JsonElement>());if(drivers.Any(d=>S(d,"paySystemId")==Selected.Id))throw new InvalidOperationException("Assign another pay system to its drivers before deleting this one.");if(!await nav.ConfirmAsync("Delete pay system",LocalizationService.Text("Delete this unused pay system?")))return;await finance.DeleteAsync("driverPaySystems",Selected.Id,Selected.Record,version,"Payouts");Selected=null;Populate();await Reload();}
}
